<?php defined( 'ABSPATH' ) || exit; $show_note = 'invoice' === $type ? LHIWC_Settings::get( 'invoice_note' ) : LHIWC_Settings::get( 'packing_note' ); $footer = LHIWC_Settings::get( 'invoice' === $type ? 'invoice_footer' : 'packing_footer' ); ?>
<?php if ( 'yes' === $show_note && $order->get_customer_note() ) : ?><section class="lhiwc-note"><h3><?php esc_html_e( 'Customer note', 'lightweight-html-invoices-for-woocommerce' ); ?></h3><p><?php echo nl2br( esc_html( $order->get_customer_note() ) ); ?></p></section><?php endif; ?><?php if ( $footer ) : ?><footer><?php echo wp_kses_post( wpautop( $footer ) ); ?></footer><?php endif; ?>
